func TestEnumMeUserLocale(t *testing.T) {
	t.Run("NewFromString_en", func(t *testing.T) {
		t.Parallel()
		val, err := NewMeUserLocaleFromString("en")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, MeUserLocale("en"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_fr", func(t *testing.T) {
		t.Parallel()
		val, err := NewMeUserLocaleFromString("fr")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, MeUserLocale("fr"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewMeUserLocaleFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewMeUserLocaleFromString("en")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

